/bin/bash -lc 'db="$PWD/assets/data/career_path.db"
python3 -c '"'import sqlite3,sys; db=sys.argv[1]; con=sqlite3.connect(\"file:\"+db+\"?mode=ro\",uri=True); rows=dict((r[0],r) for r in con.execute(\"select id,slug,stream_id,parent_id,name from career_nodes\")); ids=[2,21,24,25,42,59,67,68,71,72,73,78,161,230,241,242,272,285,287,288,303];
for i in ids:
 c=[]; seen=set(); x=i
 while x and x not in seen:
  seen.add(x); r=rows[x]; c.append(r[4]); x=r[3]
 print(i, rows[i][1], \" > \".join(reversed(c)))' \""'$db"'

